import java.util.Scanner; public class TestClass { public static void main(String[] args) { Scanner sc = new Scanner(System.in); if (!sc.hasNextLong()) return; long D = sc.nextLong(); long Oc = sc.nextLong(); long Of = sc.nextLong(); long Od = sc.nextLong(); long Cs = sc.nextLong(); long Cb = sc.nextLong(); long Cm = sc.nextLong(); long Cd = sc.nextLong(); long onlineCost; if (D <= Of) { onlineCost = Oc; } else { onlineCost = Oc + (D - Of) * Od; } long classicCost = Cb + (D / Cs) * Cm + D * Cd; if (onlineCost <= classicCost) { System.out.println("Online Taxi"); } else { System.out.println("Classic Taxi"); } sc.close(); } }